<?php

declare(strict_types=1);
/** @return list<string> */
function nexoraValidateReleaseContentManifest(ZipArchive $zip): array { $errors=[];$raw=$zip->getFromName('nexora-content-manifest.json');if(!is_string($raw))return ['nexora-content-manifest.json missing'];try{$m=json_decode($raw,true,1024,JSON_THROW_ON_ERROR);}catch(Throwable $e){return ['invalid nexora-content-manifest.json: '.$e->getMessage()];}if(($m['schema']??null)!==1||($m['algorithm']??null)!=='sha256')$errors[]='content manifest schema/algorithm invalid';$entries=(array)($m['entries']??[]);$seen=[];for($i=0;$i<$zip->numFiles;$i++){$name=(string)$zip->getNameIndex($i);if($name==='nexora-content-manifest.json')continue;$data=$zip->getFromIndex($i);if(!is_string($data)){$errors[]="unable to read release entry [{$name}]";continue;}$seen[$name]=true;$r=$entries[$name]??null;if(!is_array($r)){$errors[]="content manifest missing entry [{$name}]";continue;}if(($r['sha256']??null)!==hash('sha256',$data))$errors[]="content manifest hash mismatch [{$name}]";if((int)($r['size']??-1)!==strlen($data))$errors[]="content manifest size mismatch [{$name}]";}foreach($entries as $name=>$r)if(!isset($seen[$name]))$errors[]="content manifest references absent entry [{$name}]";return array_values(array_unique($errors));}
